44	## HttpClient Factory
45	
46	```kotlin
47	// commonMain/kotlin/network/HttpClientFactory.kt
48	object HttpClientFactory {
49	    fun create(
50	        platform: Platform,
51	        isDebug: Boolean = false
52	    ): HttpClient {
53	        return HttpClient(createEngine(platform)) {
54	            install(ContentNegotiation) {
55	                json(Json {
56	                    ignoreUnknownKeys = true
57	                    isLenient = true
58	                    encodeDefaults = false
59	                })
60	            }
61	
62	            if (isDebug) {
63	                install(Logging) {
64	                    level = LogLevel.INFO
65	                    logger = object : Logger {
66	                        override fun log(message: String) {
67	                            println("Ktor: $message")
68	                        }
69	                    }
70	                }
71	            }
72	
73	            install(Auth) {
74	                bearer {
75	                    loadTokens {
76	                        // Access Token from secure storage
77	                        BearerTokens(
78	                            accessTokenStorage.get() ?: "",
79	                            refreshTokenStorage.get() ?: ""
80	                        )
81	                    }
82	                    refreshTokens {
83	                        // Refresh token logic
84	                        val newTokens = authApi.refreshToken()
85	                        accessTokenStorage.save(newTokens.accessToken)
86	                        refreshTokenStorage.save(newTokens.refreshToken)
87	                        BearerTokens(newTokens.accessToken, newTokens.refreshToken)
88	                    }
89	                }
90	            }
91	
92	            defaultRequest {
93	                url {
94	                    protocol = URLProtocol.HTTPS
95	                    host = "api.example.com"
96	                }
97	                header("X-API-Version", "1.0")
98	                header("X-Platform", platform.name)
99	            }
100	
101	            expectSuccess = true
102	            HttpResponseValidator {
103	                handleResponseExceptionWithRequest { exception, request ->
104	                    when (exception) {
105	                        is ClientRequestException -> {
106	                            val statusCode = exception.response.status.value
107	                            when (statusCode) {
108	                                401 -> throw UnauthorizedException()
109	                                403 -> throw ForbiddenException()
110	                                404 -> throw NotFoundException()
111	                                in 500..599 -> throw ServerException()
112	                            }
113	                        }
114	                        is ServerResponseException -> throw ServerException()
115	                    }
116	                }
117	            }
118	
119	            install(ResponseObserver) {
120	                onResponse { response ->
121	                    // Track response times, errors
122	                }
123	            }
124	        }
125	    }
126	
127	    private fun createEngine(platform: Platform): HttpClientEngine {
128	        return when (platform) {
129	            Platform.ANDROID -> createOkhttpEngine()
130	            Platform.IOS -> createDarwinEngine()
131	        }
132	    }
133	}
134	```
