136	## Platform-Specific Engines
137	
138	### Android (OkHttp)
139	
140	```kotlin
141	// androidMain/kotlin/network/OkHttpEngineFactory.kt
142	fun createOkhttpEngine(): OkHttpEngine {
143	    val config = OkHttpConfig {
144	        preconfigured = OkHttpClient.Builder()
145	            .connectTimeout(30, TimeUnit.SECONDS)
146	            .readTimeout(30, TimeUnit.SECONDS)
147	            .writeTimeout(30, TimeUnit.SECONDS)
148	            .addInterceptor { chain ->
149	                val request = chain.request().newBuilder()
150	                    .header("User-Agent", "Android App/1.0")
151	                    .build()
152	                chain.proceed(request)
153	            }
154	            .addInterceptor(HttpLoggingInterceptor().apply {
155	                level = if (BuildConfig.DEBUG) {
156	                    HttpLoggingInterceptor.Level.BODY
157	                } else {
158	                    HttpLoggingInterceptor.Level.NONE
159	                }
160	            })
161	            .cache(
162	                Cache(
163	                    File(context.cacheDir, "http_cache"),
164	                    10 * 1024 * 1024 // 10MB
165	                )
166	            )
167	            .build()
168	    }
169	    return OkHttpEngine(config)
170	}
171	```
