325	## Retry Logic
326	
327	```kotlin
328	// commonMain/kotlin/network/Retry.kt
329	suspend fun <T> retryApiCall(
330	    maxRetries: Int = 3,
331	    delayMs: Long = 1000,
332	    block: suspend () -> T
333	): T {
334	    var lastException: Exception? = null
335	    repeat(maxRetries) { attempt ->
336	        try {
337	            return block()
338	        } catch (e: Exception) {
339	            lastException = e
340	            if (e is NetworkUnavailableException || e is TimeoutException) {
341	                if (attempt < maxRetries - 1) {
342	                    delay(delayMs * (attempt + 1))
343	                }
344	            } else {
345	                throw e
346	            }
347	        }
348	    }
349	    throw lastException ?: RuntimeException("Max retries exceeded")
350	}
351	```
