91	## Error Handling
92	
93	```kotlin
94	class ApiException(
95	    val statusCode: Int,
96	    override val message: String
97	) : Exception(message)
98	
99	suspend inline fun <reified T> HttpClient.safeRequest(
100	    block: HttpRequestBuilder.() -> Unit
101	): Result<T> = runCatching {
102	    val response = request(block)
103	    
104	    if (response.status.isSuccess()) {
105	        response.body<T>()
106	    } else {
107	        throw ApiException(
108	            statusCode = response.status.value,
109	            message = response.bodyAsText()
110	        )
111	    }
112	}
113	
114	// Usage
115	class UserRepository(private val api: UserApi, private val client: HttpClient) {
116	    suspend fun getUser(id: String): Result<User> {
117	        return client.safeRequest<UserDto> {
118	            url("users/$id")
119	            method = HttpMethod.Get
120	        }.map { it.toDomain() }
121	    }
122	}
123	```
